content:
import type { ReactNode } from "react";
import { cn } from "../lib/cn";
export function ControlPanelFrame({
  children,
  className,
  label = "Control panel illustration",
}: {
  children: ReactNode;
  className?: string;
  label?: string;
}) {
  return (
    <figure
      className={cn(
        "overflow-hidden rounded-xl border border-border bg-card text-card-foreground shadow-[var(--shadow-lg)]",
        className,
      )}
      data-illustration="true"
    >
      <figcaption className="flex items-center gap-2 border-b border-border bg-muted/60 px-4 py-3 text-xs font-medium text-muted-foreground">
        <span aria-hidden="true" className="size-2 rounded-full bg-border" />
        <span aria-hidden="true" className="size-2 rounded-full bg-border" />
        <span aria-hidden="true" className="size-2 rounded-full bg-border" />
        <span className="ml-2">{label}</span>
      </figcaption>
      <div className="p-5">{children}</div>
    </figure>
  );
}

import { Badge } from "./badge";
export type FeatureStatus = "included" | "optional" | "planned";
const labels: Record<FeatureStatus, string> = {
  included: "Included",
  optional: "Optional",
  planned: "Planned",
};
const variants: Record<FeatureStatus, "success" | "secondary" | "outline"> = {
  included: "success",
  optional: "secondary",
  planned: "outline",
};
export function FeatureStatusBadge({
  status,
  label,
}: {
  status: FeatureStatus;
  label?: string;
}) {
  return (
    <Badge variant={variants[status]} data-live-status="false">
      {label ?? labels[status]}
    </Badge>
  );
}

import type { ReactNode } from "react";
import { cn } from "../lib/cn";
export type ComparisonColumn = { key: string; label: string };
export type ComparisonRow = {
  feature: string;
  values: Record<string, ReactNode>;
};
export function HostingComparisonTable({
  caption,
  columns,
  rows,
  className,
}: {
  caption: string;
  columns: ComparisonColumn[];
  rows: ComparisonRow[];
  className?: string;
}) {
  return (
    <div
      className={cn(
        "overflow-x-auto rounded-xl border border-border",
        className,
      )}
    >
      <table className="w-full min-w-[42rem] border-collapse bg-card text-left text-sm">
        <caption className="sr-only">{caption}</caption>
        <thead>
          <tr className="border-b border-border bg-muted/70">
            <th scope="col" className="px-5 py-4 font-semibold">
              Feature
            </th>
            {columns.map((column) => (
              <th
                key={column.key}
                scope="col"
                className="px-5 py-4 font-semibold"
              >
                {column.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr
              key={row.feature}
              className="border-b border-border last:border-0"
            >
              <th scope="row" className="px-5 py-4 font-medium text-foreground">
                {row.feature}
              </th>
              {columns.map((column) => (
                <td
                  key={column.key}
                  className="px-5 py-4 text-muted-foreground"
                >
                  {row.values[column.key] ?? "—"}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { Check } from "lucide-react";
import { Badge } from "./badge";
import { Button } from "./button";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "./card";
export type HostingPricingCardProps = {
  name: string;
  summary: string;
  features: string[];
  priceLabel?: string;
  priceSuffix?: string;
  badge?: string;
  highlighted?: boolean;
  cta?: { href: string; label: string };
};
export function HostingPricingCard({
  name,
  summary,
  features,
  priceLabel,
  priceSuffix,
  badge,
  highlighted = false,
  cta,
}: HostingPricingCardProps) {
  return (
    <Card
      className={
        highlighted
          ? "border-primary/50 shadow-[var(--shadow-primary)]"
          : undefined
      }
    >
      <CardHeader>
        {badge ? <Badge variant="secondary">{badge}</Badge> : null}
        <CardTitle className="mt-4">{name}</CardTitle>
        <p className="mt-2 text-sm leading-6 text-muted-foreground">
          {summary}
        </p>
      </CardHeader>
      <CardContent>
        {priceLabel ? (
          <p className="mb-6 flex items-baseline gap-1">
            <span className="text-3xl font-semibold tracking-[-0.035em]">
              {priceLabel}
            </span>
            {priceSuffix ? (
              <span className="text-sm text-muted-foreground">
                {priceSuffix}
              </span>
            ) : null}
          </p>
        ) : null}
        <ul className="grid gap-3" aria-label={`${name} features`}>
          {features.map((feature) => (
            <li
              key={feature}
              className="flex gap-2 text-sm text-muted-foreground"
            >
              <Check
                aria-hidden="true"
                className="mt-0.5 size-4 shrink-0 text-primary"
              />
              <span>{feature}</span>
            </li>
          ))}
        </ul>
      </CardContent>
      {cta ? (
        <CardFooter>
          <Button asChild className="w-full">
            <a href={cta.href}>{cta.label}</a>
          </Button>
        </CardFooter>
      ) : null}
    </Card>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "../lib/cn";
export function Container({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn("site-container", className)} {...props} />;
}
export function Section({ className, ...props }: ComponentProps<"section">) {
  return <section className={cn("site-section", className)} {...props} />;
}
export function HeroPattern({
  eyebrow,
  title,
  description,
  actions,
  visual,
  className,
  ...props
}: ComponentProps<"section"> & {
  eyebrow?: string;
  title: string;
  description: string;
  actions?: ReactNode;
  visual?: ReactNode;
}) {
  return (
    <section
      className={cn(
        "relative overflow-hidden bg-[var(--gradient-hero)] py-[var(--site-hero-space)]",
        className,
      )}
      {...props}
    >
      <Container className="grid items-center gap-12 lg:grid-cols-[1.05fr_0.95fr]">
        <div>
          {eyebrow ? (
            <p className="mb-5 text-xs font-bold uppercase tracking-[var(--tracking-label)] text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h1 className="max-w-[12ch] text-[length:var(--text-display)] font-semibold leading-[var(--leading-display)] tracking-[var(--tracking-display)]">
            {title}
          </h1>
          <p className="mt-6 max-w-[42rem] text-[length:var(--text-body-lg)] leading-8 text-muted-foreground">
            {description}
          </p>
          {actions ? (
            <div className="mt-8 flex flex-wrap gap-3">{actions}</div>
          ) : null}
        </div>
        {visual ? <div>{visual}</div> : null}
      </Container>
    </section>
  );
}
export function FeatureGrid({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "grid gap-[var(--site-grid-gap)] md:grid-cols-2 xl:grid-cols-3",
        className,
      )}
      {...props}
    />
  );
}
export function TrustStrip({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "grid gap-3 rounded-xl border border-border bg-card p-5 text-sm text-muted-foreground sm:grid-cols-3",
        className,
      )}
      {...props}
    />
  );
}
export function InfrastructurePanel({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "rounded-xl border border-border bg-[var(--gradient-panel)] p-6 shadow-[var(--shadow-md)]",
        className,
      )}
      {...props}
    />
  );
}

export * from "./components/accordion";
export * from "./components/badge";
export * from "./components/button";
export * from "./components/callout";
export * from "./components/card";
export * from "./components/control-panel-frame";
export * from "./components/dialog";
export * from "./components/feature-status-badge";
export * from "./components/hosting-comparison-table";
export * from "./components/hosting-pricing-card";
export * from "./components/layout-patterns";
export * from "./components/navigation-menu";
export * from "./components/tabs";
export * from "./components/tooltip";
export * from "./lib/cn";

import { DesignSystemFixture } from "@/components/design-system/design-system-fixture";
export default function HomePage() {
  return <DesignSystemFixture />;
}

